export function parseCsv(raw: string): string[][] {
  return raw.trim().split("\n").map((r) => r.split(","));
}

export function formatInvoiceTotal(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

export const BASE_DELAY_MS = 250;
export const MAX_JITTER_RATIO = 0.35;
export const MAX_ATTEMPTS = 6;

export class WorkerPool {
  private idle: unknown[] = [];
  release(w: unknown) { this.idle.push(w); }
}
